from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 220, "תרשים א: שני גופים A ו-B צמודים זה לזה על משטח אופקי, וכוח F דוחף את A. תרשים ב: גוף B מונח על גוף A, וכוח F דוחף את A")
    g.ground(30, 260, 110)
    g.block(130, 88, 44, 44, "A"); g.block(172, 92, 36, 36, "B"); g.arrow(60, 80, 106, 80, "F", lx=70, ly=70)
    g.heb(150, 140, "תרשים א")
    g.ground(300, 530, 190)
    g.block(400, 168, 50, 44, "A"); g.block(400, 128, 36, 36, "B"); g.arrow(330, 160, 373, 160, "F", lx=340, ly=150)
    g.heb(420, 214, "תרשים ב")
    return g

def blk(forces, lab, alt, note):
    return lambda: fbd(forces, alt + ". הכיוון החיובי ימינה, כיוון התנועה", positive=0, body="block", body_label=lab, surface="below", note=note)

E(id="bagrut-2009-q2", year=2009, label="2009 שאלה 2", topic="dynamics", sub="dyn-friction", diff=3, fig=fig,
  stem=r"שני גופים, $A$ ו-$B$, צמודים זה לזה על משטח אופקי לא חלק. ברגע מסוים מפעילים על גוף $A$ כוח אופקי קבוע $F$, כמו בתרשים א, והגופים מתחילים לנוע ימינה.",
  parts=[
    P("א", r"בזמן התנועה, האם הכוח שגוף $A$ מפעיל על גוף $B$ גדול מהכוח שגוף $B$ מפעיל על גוף $A$, קטן ממנו או שווה לו? נמקו.", choice(["גדול", "קטן", "שווה"], 2), ["principle"], [
        S(r"החוק השלישי של ניוטון", r"הכוחות ששני גופים מפעילים זה על זה תמיד שווים בגודלם והפוכים בכיוונם, גם כשיש תאוצה", r"\vec N_{AB} = -\vec N_{BA}", eq=r"\vec F_{1,2} = -\vec F_{2,1}"),
    ], r"שווה", key=r"שווים, לפי החוק השלישי"),
    P("ב", r"נתון: $m_B = 2\,\text{kg}$, $m_A = 3\,\text{kg}$, $F = 13\,\text{N}$. מקדם החיכוך הקינטי בין כל גוף למשטח $\mu_k = 0.1$. מה הכוח שגוף $A$ מפעיל על גוף $B$?", num(5.2, "N"), ["fbd", "principle", "algebra"], [
        X(r"הכיוון החיובי ימינה, כיוון התנועה. בוחרים אותו, כי השאלה לא קבעה כיוון. בציר האנכי כל גוף במנוחה, ולכן הכוח הנורמלי של המשטח על כל גוף שווה למשקל שלו."),
        D(r"תרשים הכוחות על גוף A", blk([("F", 0, 1.3), ("N_BA", 180, 0.75), ("f_kA", 180, 0.35, 18), ("N_A", 90, 1.0), ("m_A g", -90, 1.0)], "A",
            "תרשים כוחות על גוף A: הכוח F ימינה, הכוח הנורמלי של B על A שמאלה, חיכוך קינטי שמאלה, הכוח הנורמלי של המשטח כלפי מעלה וכוח הכובד כלפי מטה", "נדחף")),
        D(r"תרשים הכוחות על גוף B", blk([("N_AB", 0, 0.6), ("f_kB", 180, 0.3), ("N_B", 90, 0.8), ("m_B g", -90, 0.8)], "B",
            "תרשים כוחות על גוף B: הכוח הנורמלי של A על B ימינה, חיכוך קינטי שמאלה, הכוח הנורמלי של המשטח כלפי מעלה וכוח הכובד כלפי מטה", "נדחף על ידי A")),
        S(r"משוואות הכוחות", r"לגוף A: הכוח F, פחות הכוח הנורמלי של B ופחות החיכוך הקינטי. לגוף B: הכוח הנורמלי של A, פחות החיכוך הקינטי", r"F - N_{BA} - f_{kA} = m_A a \qquad N_{AB} - f_{kB} = m_B a", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מציבים את כוחות החיכוך", r"החיכוך הקינטי הוא מקדם החיכוך כפול הכוח הנורמלי של המשטח, וכל כוח נורמלי כזה שווה למשקל של הגוף", r"f_{kA} = \mu N_A = \mu m_A g \qquad f_{kB} = \mu N_B = \mu m_B g", eq=r"f_k = \mu_k N"),
        S(r"מחברים", r"שני הכוחות הנורמליים שבין הגופים שווים בגודלם, לפי סעיף א, ולכן מתבטלים", r"F - \mu (m_A + m_B)\,g = (m_A + m_B)\,a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"מחלקים במסה הכוללת", r"a = \frac{13 - 0.1 \cdot 5 \cdot 10}{5} = \frac{13 - 5}{5} = 1.6\,\text{m/s}^2"),
        S(r"הכוח של A על B", r"מבודדים אותו מהמשוואה של גוף B ומציבים", r"N_{AB} = m_B a + \mu m_B g = 2 \cdot 1.6 + 0.1 \cdot 20 = 5.2\,\text{N}"),
    ], r"$5.2\,\text{N}$", key=r"5.2 N"),
    P("ג", r"הכוח $F$ פועל רק כמה שניות. אחרי שהוא מפסיק לפעול, מה הכוח שגוף $A$ מפעיל על גוף $B$? פרטו. (התייחסו לגופים כאל גופים קשיחים.)", num(0, "N"), ["fbd", "principle", "algebra"], [
        X(r"בודקים מה הייתה התאוצה של כל גוף אילו נע לבד, בלי כוח ביניהם. אחרי שהכוח $F$ מפסיק, הכוח האופקי היחיד על כל גוף הוא החיכוך, נגד כיוון התנועה."),
        D(r"אחרי שהכוח הפסיק: תרשים הכוחות על כל גוף", blk([("f_k", 180, 0.35), ("N", 90, 1.0), ("mg", -90, 1.0)], None,
            "תרשים כוחות על גוף אחרי שהכוח F הפסיק: רק חיכוך קינטי שמאלה, הכוח הנורמלי כלפי מעלה וכוח הכובד כלפי מטה", "הכוח F הפסיק")),
        S(r"משוואת כוחות לגוף A", r"בכיוון החיובי לא פועל אף כוח. נגדו פועל החיכוך הקינטי", r"0 - f_{kA} = m_A a_A \;\Rightarrow\; -\mu m_A g = m_A a_A", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"המסה מופיעה בשני האגפים, ולכן היא מצטמצמת: התאוצה לא תלויה במסה", r"a_A = -\mu g = -0.1 \cdot 10 = -1\,\text{m/s}^2"),
        S(r"משוואת כוחות לגוף B, ומחלקים במסה", r"אותו חישוב בדיוק, והמסה שוב מצטמצמת", r"0 - f_{kB} = m_B a_B \;\Rightarrow\; a_B = -\mu g = -1\,\text{m/s}^2"),
        S(r"מסקנה", r"לשני הגופים אותה האטה גם בלי לדחוף זה את זה, ולכן אין צורך בכוח ביניהם", r"a_A = a_B \;\Rightarrow\; N_{AB} = 0"),
    ], r"$0$: לשני הגופים אותה האטה, $\mu g = 1\,\text{m/s}^2$, ולכן הם לא לוחצים זה על זה"),
    P("ד", r"איזה מההיגדים נכון? נמקו. (1) ברגע שהכוח $F$ מפסיק לפעול, שני הגופים נעצרים מיד. (2) אחרי שהכוח $F$ מפסיק, שני הגופים נעצרים אחרי אותו זמן (גדול מ-$0$). (3) אחרי שהכוח $F$ מפסיק, גוף $A$ נעצר לפני גוף $B$.", choice(["(1)", "(2)", "(3)"], 2), ["principle", "fbd", "understanding"], [
        X(r"בזמן הדחיפה גוף $A$ דוחף את גוף $B$, ולכן הגופים לחוצים זה אל זה, ופועל ביניהם כוח נורמלי. ברגע שהכוח $F$ מפסיק, הלחץ הזה לא נעלם מיד: בזמן הניתוק עדיין פועל בין הגופים כוח נורמלי."),
        D(r"בזמן הניתוק: תרשים הכוחות על גוף B", blk([("N_AB", 0, 0.4), ("f_kB", 180, 0.3), ("N_B", 90, 0.8), ("m_B g", -90, 0.8)], "B",
            "תרשים כוחות על גוף B בזמן הניתוק: הכוח הנורמלי של A ימינה, חיכוך שמאלה, הכוח הנורמלי של המשטח וכוח הכובד", "בזמן הניתוק")),
        S(r"הכוח הנורמלי על גוף B", r"גוף A דוחף את B קדימה, ולכן הכוח הזה בכיוון החיובי ומקטין את ההאטה של B", r"N_{AB} - f_{kB} = m_B a_B \;\Rightarrow\; |a_B| < \mu g", eq=r"\Sigma\vec F = m\vec a"),
        D(r"בזמן הניתוק: תרשים הכוחות על גוף A", blk([("N_BA", 180, 0.8), ("f_kA", 180, 0.3, 22), ("N_A", 90, 1.0), ("m_A g", -90, 1.0)], "A",
            "תרשים כוחות על גוף A בזמן הניתוק: הכוח הנורמלי של B שמאלה, חיכוך שמאלה, הכוח הנורמלי של המשטח וכוח הכובד", "בזמן הניתוק")),
        S(r"הכוח הנורמלי על גוף A", r"לפי החוק השלישי, גוף B דוחף את A בכוח שווה והפוך, כלומר נגד כיוון התנועה. הכוח הזה מצטרף לחיכוך ומגדיל את ההאטה של A", r"0 - N_{BA} - f_{kA} = m_A a_A \;\Rightarrow\; |a_A| > \mu g", eq=r"\vec F_{1,2} = -\vec F_{2,1}"),
        S(r"מסקנה", r"בזמן הניתוק גוף A מאט יותר מגוף B, ולכן המהירות שלו קטנה יותר והגופים נפרדים. אחר כך לשניהם אותה האטה, ולכן A, שהתחיל עם מהירות קטנה יותר, נעצר ראשון", r"|a_A| > |a_B| \;\Rightarrow\; v_A < v_B \;\Rightarrow\; t_A < t_B"),
        X(r"* דוגמה נוספת למי שרוצה: אפשר לדמיין קפיץ קטן ודחוס בין שני הגופים. בזמן הדחיפה הקפיץ נדחס. כשהכוח $F$ מפסיק, הקפיץ משתחרר ודוחף את $B$ קדימה ואת $A$ אחורה, ולכן $A$ נעצר קודם."),
    ], r"היגד (3): בזמן הניתוק הכוח הנורמלי פועל על $B$ בכיוון התנועה ועל $A$ נגד כיוון התנועה, ולכן $A$ נעצר ראשון", key=r"(3)"),
    P("ה", r"במקרה אחר מדביקים את גוף $B$ על גוף $A$ (תרשים ב), ומפעילים על גוף $A$ אותו כוח כמו בסעיף ב. האם התאוצה של הגופים עכשיו גדולה מהתאוצה בסעיף ב, שווה לה או קטנה ממנה? נמקו.", choice(["גדולה", "שווה", "קטנה"], 1), ["fbd", "principle"], [
        D(r"תרשים הכוחות על שני הגופים יחד (M היא המסה של שניהם)", blk([("F", 0, 1.3), ("f_k", 180, 0.5), ("N", 90, 1.2), ("Mg", -90, 1.2)], "A+B",
            "תרשים כוחות על שני הגופים יחד: הכוח F ימינה, חיכוך שמאלה, הכוח הנורמלי של המשטח כלפי מעלה וכוח הכובד של שניהם כלפי מטה", "מודבקים")),
        S(r"משוואת כוחות בציר האנכי", r"רק גוף A נוגע במשטח, והוא נושא את שני הגופים. לכן הכוח הנורמלי שווה למשקל של שניהם, כמו קודם", r"N - (m_A + m_B)\,g = 0 \;\Rightarrow\; N = 50\,\text{N}", eq=r"\Sigma\vec F = m\vec a"),
        S(r"משוואת כוחות בכיוון התנועה", r"אותו כוח, ואותו חיכוך כולל", r"F - f_k = (m_A + m_B)\,a,\quad f_k = \mu N \;\Rightarrow\; 13 - 5 = 5a", eq=r"f_k = \mu_k N"),
        S(r"מחלקים את משוואת הכוחות במסה", r"אותה תאוצה כמו בסעיף ב", r"a = 1.6\,\text{m/s}^2"),
    ], r"שווה", key=r"התאוצות שוות"),
  ],
  concepts=["החוק השלישי של ניוטון", "כוח מגע בין גופים", "חיכוך קינטי", "מערכת גופים"],
  summary=r"שני גופים שנדחפים יחד על משטח עם חיכוך: הכוח ביניהם, מה קורה כשהדחיפה נפסקת, ולמה גוף על גוף לא משנה את התאוצה.",
  review='הנחה שלי (לפי החלטת הבעלים).\nסעיף ג: לגופים קשיחים הכוח בין הגופים אחרי שהכוח מפסיק הוא 0. בפתרון מוצגת משוואת הכוחות לכל גוף, והחלוקה במסה מצוינת במפורש.\nסעיף ד: ההסבר הראשי הוא הכוח הנורמלי בזמן הניתוק: על B בכיוון התנועה ועל A נגד כיוון התנועה, ולכן A נעצר ראשון. האנלוגיה של הקפיץ (ההסבר מדף התשובות) מופיעה בסוף, בכוכבית, כדוגמה נוספת.\nמה לבדוק: את הניסוח של שני הסעיפים.')
